import json, math

def verify(answer):
    """Mechanical GRPO verifier for batch-005 scenario 1 (The Interior Eight Yards).
    Recomputes the competing-risk hazard values and interior maximum, the feasible-window
    argmin, the mean/median skew ratio, the overlapping-band comparison veto, and the
    drawdown recovery fraction; checks all veto flags and the fail-closed decision."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    expected = {
        "hazard_at_2yd", "hazard_at_8yd", "hazard_at_10yd",
        "interior_peak_depth_yd", "interior_peak_is_maximum", "deeper_is_safer_admissible",
        "optimal_depth_under_min2_constraint", "mean_player_value", "median_player_value",
        "mean_median_skew_ratio", "report_mean_as_typical_admissible", "grade_difference",
        "combined_error_band", "ranking_resolved", "drawdown_recovery_fraction", "depth_decision",
    }
    if set(answer.keys()) != expected:
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    def close(key, val, rel=1e-6, abs_=1e-9):
        x = answer.get(key)
        return num(x) and math.isclose(x, val, rel_tol=rel, abs_tol=abs_)
    # (1) Competing-risk hazard [6aeb75fe28eb9cd8:p6, p.265]
    def h(d):
        return 6 + 0.8 * d - 0.05 * d * d
    if not close("hazard_at_2yd", h(2)):
        return False
    if not close("hazard_at_8yd", h(8)):
        return False
    if not close("hazard_at_10yd", h(10)):
        return False
    peak = 0.8 / (2 * 0.05)  # h'(d)=0.8-0.1d=0 -> d=8; h''=-0.1<0 -> maximum
    if not close("interior_peak_depth_yd", peak):
        return False
    if answer.get("interior_peak_is_maximum") is not True:
        return False
    if answer.get("deeper_is_safer_admissible") is not False:
        return False
    grid = [2 + i * 0.01 for i in range(801)]  # [2,10]
    d_min = min(grid, key=h)
    if not close("optimal_depth_under_min2_constraint", d_min, rel=0.0, abs_=0.02):
        return False
    # (2) Skew [366ba522490b1573:p2, p.27]
    vals = [2.0] * 9 + [20.0]
    mean = sum(vals) / len(vals)  # 3.8
    median = sorted(vals)[len(vals) // 2]  # 2.0 (10 values, upper middle = 2.0)
    if not close("mean_player_value", mean):
        return False
    if not close("median_player_value", median):
        return False
    if not close("mean_median_skew_ratio", mean / median):
        return False
    if answer.get("report_mean_as_typical_admissible") is not False:
        return False
    # (3) Overlapping-band comparison veto [366ba522490b1573:p3, p.55]
    if not close("grade_difference", 101 - 98):
        return False
    if not close("combined_error_band", 3 + 3):
        return False
    if answer.get("ranking_resolved") is not ((101 - 98) > (3 + 3)):
        return False
    # (4) Drawdown recovery [366ba522490b1573:p6, p.110]
    c = 0.5
    if not close("drawdown_recovery_fraction", c / (1 - c)):
        return False
    # Fail-closed decision
    if answer.get("depth_decision") != "veto_and_recompute":
        return False
    return True

