    def close(key, val, rel=1e-6, abs_=1e-9):
        x = answer.get(key)
        return num(x) and math.isclose(x, val, rel_tol=rel, abs_tol=abs_)
    # (1) Chain amplification [1cfd792f9b7396d1:p1, p.41]
    nu, p_prop = 4, 0.5
    b = nu * p_prop  # 2.0
    chain = sum(b ** k for k in range(3))  # 1+2+4 = 7
